G_delta_alpha <- function(u, delta = 0, alpha = 1) {
  stopifnot(is.numeric(u), length(delta) == 1, length(alpha) == 1, alpha > 0)

  if (delta == 0) {
    return(u)
  } else {
    if (alpha == 1) {
      z <- u * exp(delta / 2 * u^2)
    } else {
      z <- u * exp(delta / 2 * (u^2)^alpha)
    }
    return(z)
  }
}

