rolling_incidence_7d <- function(data, population, date_col = "date", cases_col = "cases") {
  stopifnot(is.data.frame(data), length(population) == 1L, is.finite(population))
  if (population <= 0) stop("population must be a positive count")
  if (!all(c(date_col, cases_col) %in% names(data))) stop("required columns are missing")
  dates <- as.Date(data[[date_col]])
  cases <- as.numeric(data[[cases_col]])
  if (anyNA(dates) || any(cases < 0, na.rm = TRUE)) stop("invalid dates or case counts")
  # Sort observations before checking surveillance-day continuity.
  ord <- order(dates)
  x <- data.frame(date = dates[ord], cases = cases[ord])
  if (anyDuplicated(x$date)) stop("dates must be unique")
  # Gaps would make a seven-row window differ from seven calendar days.
  if (nrow(x) > 1L && any(diff(x$date) != 1)) stop("dates must be consecutive")
  # Incidence is expressed as cases per 100,000 population over seven days.
  rolling <- slider::slide_dbl(x$cases, sum, .before = 6L, .complete = TRUE)
  out <- x |>
    dplyr::mutate(cases_7d = rolling, incidence_7d_per_100k = rolling / population * 1e5)
  return(out)
}

